#include <stdio.h>
#include <stdint.h>
#include <jemalloc/jemalloc.h>

void print_frag(void) {
    uint64_t epoch = 1;
    size_t sz = sizeof(epoch);
    mallctl("epoch", &epoch, &sz, &epoch, sz);   /* refresh stats */

    size_t allocated, active, resident;
    sz = sizeof(size_t);
    mallctl("stats.allocated", &allocated, &sz, NULL, 0);
    mallctl("stats.active", &active, &sz, NULL, 0);
    mallctl("stats.resident", &resident, &sz, NULL, 0);

    printf("allocated %zu  active %zu  resident %zu\n",
           allocated, active, resident);
    printf("page slack (active/allocated) %.2f\n",
           (double)active / allocated);
    printf("dirty+meta (resident/active) %.2f\n",
           (double)resident / active);
}
